-- One-time owner-authorised Tapkin policy publication, editable in the CMS.
-- Preserve previous sections hidden for review. Do not alter Kosykin or settings.
DO $tapkin_policies$
DECLARE
  store_id uuid;
  page_id uuid;
  page jsonb;
  section jsonb;
  position integer;
  page_position integer := 0;
  release_id uuid;
BEGIN
  SELECT id INTO store_id FROM "Store" WHERE slug = 'tapkin';
  IF store_id IS NULL THEN RETURN; END IF;
  FOR page IN SELECT value FROM jsonb_array_elements($content$[{"slug":"terms","name":"Terms & Conditions","description":"Tapkin Australian terms for NFC pet tags, activation, public profiles, custom products, delivery, cancellations, consumer rights and customer points.","sections":[{"name":"About these terms","type":"RICH_TEXT","content":{"headline":"About these terms","copy":"Updated 13 October 2026. Tapkin is a registered Australian business name providing NFC-enabled products, linked online profiles and any other products expressly offered in our shop. These terms apply to this store, purchases and use of the linked profile service, together with the listing, options and any custom quote you accept. Seller information at the end identifies Tapkin and ABN 84 884 117 384. Our Privacy policy explains information handling. Optional features apply only when offered; describing them here does not make an unavailable feature part of your purchase.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Your Australian consumer rights","type":"RICH_TEXT","content":{"headline":"Your Australian consumer rights","copy":"Nothing in these terms excludes, restricts or modifies rights or remedies that cannot lawfully be excluded, including under the Australian Consumer Law. Products must meet applicable consumer guarantees, including acceptable quality, correspondence with their description and fitness for a purpose you tell us about and we accept. These protections also apply to personalised, made-to-order and discounted goods. A stated product warranty is additional to, and does not replace, these rights.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Choosing products and using them safely","type":"RICH_TEXT","content":{"headline":"Choosing products and using them safely","copy":"Check the listing for dimensions, material, finish, phone compatibility, included parts, intended use, attachment and care instructions. NFC requires a compatible enabled phone near the tag; accessing an online profile also requires an internet connection. Do not assume every phone or case will work in every position. Layer lines and slight colour variation may be normal features of accurately described 3D printing, but do not excuse defects. Use pet accessories as directed, inspect attachments and replace damaged items. Keep small parts away from children and do not let animals chew or swallow tags. Do not assume an item is a toy, restraint, food-contact safe, waterproof or heat resistant unless its listing supports that use. Ask before buying about a particular purpose.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"NFC is identification, not GPS or an emergency service","type":"RICH_TEXT","content":{"headline":"NFC is identification, not GPS or an emergency service","copy":"A Tapkin NFC tag opens a linked profile when someone deliberately taps it with a compatible phone. It does not continuously transmit its position, contain GPS tracking or guarantee that a missing pet or item will be found. It does not replace a pet microchip, legally required identification or registration, supervision, veterinary care or emergency services. Contact the relevant authority or emergency service directly when needed. Phone, internet and messaging availability affect access; these practical limitations do not exclude consumer guarantees or promises expressly made in the listing.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Public profiles and authority to share","type":"RICH_TEXT","content":{"headline":"Public profiles and authority to share","copy":"When you make a profile public, anyone with its link or a readable tag can access the displayed information, not just a verified finder. A link can be copied or forwarded. Publish only details you intend to disclose and have authority to share, including another contact person’s consent. Pet-care fields should contain relevant animal information, not unnecessary private human health or identity information. Public pages ask search engines not to index them, but this is not a password or guarantee against copies or indexing. You can change visibility or disable a tag through available account controls; this stops future access through our service but cannot recall copies already made. Do not publish home addresses, private documents or information about a child unless expressly needed, supported and lawfully authorised.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Optional finder location and external services","type":"RICH_TEXT","content":{"headline":"Optional finder location and external services","copy":"Where offered, Share location asks the visitor’s browser for permission and opens their SMS app with a map link to their current location addressed to the profile contact. The visitor decides whether to send it. This is the visitor’s location at that moment, not a tracked pet or tag position. Calling, SMS and map services are provided by third parties and may incur their normal charges. Verify information and use care when contacting an unknown finder; Tapkin does not verify the identity or accuracy of every visitor or message.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Linked service availability and changes","type":"RICH_TEXT","content":{"headline":"Linked service availability and changes","copy":"Online profiles depend on hosting, maintenance, security and network availability. Any stated included service period or fee in the listing forms part of the purchase; these terms do not create a new subscription, recurring charge or lifetime guarantee. We do not promise uninterrupted access, but must supply services with applicable consumer guarantees. We take reasonable steps to address faults, communicate significant planned changes and preserve legally required remedies. We will not materially withdraw a purchased entitlement or impose a new charge without addressing the agreement and your rights. If a service is permanently retired, we will provide appropriate notice, available data-access options and any remedy required by law. Keep a separate copy of important contact information.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Prices, payment and availability","type":"RICH_TEXT","content":{"headline":"Prices, payment and availability","copy":"Prices are in Australian dollars. Any GST applicable to the sale is included in the displayed consumer price. Delivery and any selected paid options are shown before payment. Stripe processes payment using the methods offered at checkout; we do not store full card details. A pending checkout or payment receipt alone does not mean an item has shipped. We confirm payment and order progress separately. If checkout is closed, a product is unavailable or an address cannot be served, an order cannot be completed through that checkout.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Order acceptance and genuine mistakes","type":"RICH_TEXT","content":{"headline":"Order acceptance and genuine mistakes","copy":"Check the product, quantity, personalisation, email and delivery address before paying. We may need to review a custom request, stock availability, a suspected payment problem or a clear pricing error before accepting or making the order. We will contact you through your verified ticket channel if a paid order cannot be supplied as agreed, explain the issue and offer an appropriate alternative for you to accept or a refund. We will not charge a higher price or substitute a materially different product without your agreement. We do not reserve a blanket right to cancel an accepted order at our discretion.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Personalisation and customer designs","type":"RICH_TEXT","content":{"headline":"Personalisation and customer designs","copy":"Check spelling, names, sizes and other instructions before paying. A custom request is accepted only after we confirm feasibility, scope, price and relevant timing. Submit files, artwork, names and logos only when you own or have permission to use them for the requested work. You retain rights you own and give us limited permission to inspect, adapt as agreed, manufacture and handle files for your job and related support, not to resell your design. Rights in newly commissioned design work must be agreed in the quote. We may decline infringing, malicious or unsafe requests. We do not publish customer designs in marketing without separate permission. An approved proof or your instructions do not remove our duty to supply the agreed item and meet consumer guarantees.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Production, changes and cancellation requests","type":"RICH_TEXT","content":{"headline":"Production, changes and cancellation requests","copy":"We accept a change-of-mind cancellation when manufacturing or preparation has not started. Submit a verified cancellation request promptly through Help & requests. Eligible requests can pause the order while we review it; check the ticket for confirmation. A request or pause is not itself a confirmed cancellation or refund. Once preparation or manufacturing has started, we do not offer change-of-mind cancellation, and changes may be unavailable. This restriction does not apply to a remedy you are legally entitled to for a failure, misleading description or other breach. We will not use a slow ticket response to disregard a request received while the order was still eligible.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Delivery and order tracking","type":"RICH_TEXT","content":{"headline":"Delivery and order tracking","copy":"We deliver to eligible Australian addresses and carrier services shown at checkout; not every postcode, PO box or parcel locker is necessarily supported. Check the full address and any address suggestion before payment. Request changes promptly through a verified ticket; we confirm feasibility and any genuine additional cost before proceeding. Production time and carrier transit time are separate. Dates are estimates unless expressly agreed as a commitment. Shippit and the relevant carrier receive delivery information and supply tracking updates. A label is not proof of collection, and a delivered scan is not conclusive proof against a missing-parcel claim. Contact us about missing, damaged or significantly delayed parcels. We investigate and remain responsible for addressing our supply obligations, rather than requiring you to resolve them with the carrier alone.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Returns and remedies","type":"RICH_TEXT","content":{"headline":"Returns and remedies","copy":"We do not offer returns or exchanges solely because you changed your mind, chose an unsuitable option where the listing was accurate, or no longer want an accurately supplied item. This is separate from eligible pre-preparation cancellation and never removes mandatory rights. For faulty, unsafe, wrongly supplied or materially misdescribed goods or a deficient included service, use Help & requests and provide reasonable proof of purchase. We may reasonably assess the issue. A major product failure can entitle you to choose a refund or replacement; minor failures require an appropriate remedy within a reasonable time, with further remedies if not fixed. Compensation and service cancellation rights may also apply. Personalised, discounted and NFC-enabled products remain covered. We do not impose a blanket short defect-claim deadline, require original packaging or force points or credit instead of a monetary refund legally due.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Return handling and refunds","type":"RICH_TEXT","content":{"headline":"Return handling and refunds","copy":"Contact us for return instructions and a confirmed address before posting. Where a fault is confirmed, we reimburse reasonable return postage and arrange or cover reasonable transport for items too large or difficult to return. We do not charge a restocking or processing fee for a remedy legally due for a faulty item. Any proposed assessment or transport cost where no covered failure is found is explained and agreed beforehand. We normally refund through the original payment method unless you agree otherwise; bank processing times vary. Do not discard reasonable purchase evidence, but an order number is not the only proof we can accept. If an item seems unsafe, stop using it and flag the issue promptly.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Accounts and verified guest access","type":"RICH_TEXT","content":{"headline":"Accounts and verified guest access","copy":"Shopping and support features depend on what the store offers. An account is required to activate and manage an NFC tag and its profile; purchase alone does not publish a profile. Email sign-in is available, with Google and Apple only when offered and selected. Keep passwords, verification and activation codes confidential. Activate only products you own or are authorised to manage, keep profile/contact details current and check the public preview. Use supported privacy, disable and transfer controls; report lost or compromised tags through your account and support. Guest support verifies the relevant email, and an account is not required to exercise consumer rights. For lost-access or accessibility problems, use the assistance instructions on Help & requests.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Customer points and promotions","type":"RICH_TEXT","content":{"headline":"Customer points and promotions","copy":"If enabled, customer points are promotional discounts on eligible future Tapkin purchases, not money, purchased gift cards, transferable funds or an automatic entitlement at Kosykin. Current earning, redemption units, minimums, discount caps, combination rules and expiry are shown in your account and checkout; the applicable rules are recorded with the order. Eligible guest awards can be claimed only after verification of the purchase email. Cancelled or unpaid orders do not earn confirmed points. Points reserved in checkout are committed on confirmed payment or released when the checkout fails or expires. Confirmed refunds proportionally reverse earnings and restore redeemed points with their original expiry; expired points are not revived. Already-spent earnings may offset other or future credits but do not create a cash debt. A refund normally concerns money actually paid, and adjustments never remove mandatory consumer remedies. We explain future programme changes and treatment of outstanding usable balances rather than silently deleting them.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Customer service and complaints","type":"RICH_TEXT","content":{"headline":"Customer service and complaints","copy":"Our customer service channel is the website ticket system: Account → Help & requests, or verified guest access on the help page. Our initial response target is five business days, excluding weekends and store holidays in Australia/Adelaide; this is not a guaranteed resolution time and does not limit legal rights. Keep related messages in the same ticket. Email notifications direct you back to it; replies to outgoing notification emails are not monitored. Social media is not a verified order-support channel. Ask us to review an unresolved complaint in your ticket; you may also seek help from your state or territory consumer protection agency.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Website content and acceptable use","type":"RICH_TEXT","content":{"headline":"Website content and acceptable use","copy":"Our site content and designs are protected by applicable intellectual-property rights. You may use the site for personal shopping and ordinary product research. Do not misuse accounts, scrape private customer information, submit malicious files, impersonate others, evade security controls or use the service for unlawful activity. We may proportionately restrict misuse or a compromised account to protect customers, explain the reason where safe and allow a review. Restrictions do not remove your existing order entitlements or lawful access requests.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Limits, changes and disputes","type":"RICH_TEXT","content":{"headline":"Limits, changes and disputes","copy":"We do not exclude liability that Australian law does not allow us to exclude, or require you to indemnify us for our own negligence or breach. Liability and compensation are determined under applicable law, not a blanket purchase-price cap. Updated terms apply to future purchases; they do not retrospectively remove rights from an accepted order. If a term cannot be enforced, the remaining lawful terms continue. Applicable Australian law governs, and you retain access to courts, tribunals and consumer agencies available to you; these terms do not require you to litigate only in our home state.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}}]},{"slug":"privacy","name":"Privacy Policy","description":"How Tapkin handles accounts, NFC profiles, scan diagnostics, optional visitor location sharing, orders, providers, tracking consent and privacy requests.","sections":[{"name":"Who we are and what this policy covers","type":"RICH_TEXT","content":{"headline":"Who we are and what this policy covers","copy":"Updated 13 October 2026. Tapkin is a registered Australian business name, ABN 84 884 117 384, operated by the same proprietor as Kosykin. This policy covers this store, customer accounts, orders, support tickets, NFC activation, linked profiles and visits to public tag pages. We follow Australian privacy requirements that apply to us. Small-business exemptions have exceptions; we do not assume an exemption or remove applicable rights. Contact us through Help & requests, select a Privacy ticket and use verified guest access if you have no account. If verification or accessibility prevents access, use the help page’s assistance instructions.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Information you provide","type":"RICH_TEXT","content":{"headline":"Information you provide","copy":"We handle name, email, phone, delivery and account details, orders, selected options, personalisation, prices, payment references and delivery status. Account features may store addresses, preferences, authentication-provider links, points and supported saved shopping data. Support tickets contain messages and information you choose to provide, and accepted custom work can include artwork or files. NFC records include tag identifiers, activation and ownership associations, visibility, status and profile edits. Pet profiles can include a name, photo, species, breed, approximate age, description, care or behaviour notes, veterinarian details and contact people’s names, relationships and phone numbers. Provide only relevant information and obtain authority for other people’s details. Do not submit unnecessary human health information, identity documents, full card details or private child information.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Technical information and where it comes from","type":"RICH_TEXT","content":{"headline":"Technical information and where it comes from","copy":"Hosting and security systems process IP addresses, browser/device details, request logs, session identifiers, timestamps and security events. We obtain information from you, the sign-in provider you choose, Stripe payment confirmations, Shippit and carrier tracking, and optional consented measurement services. Public tag access can create a scan record containing the tag identifier, timestamp/day, broad device category and country or region if supplied by the request infrastructure. Those regions are approximate, can be absent or incorrect and are not a live tag position. Raw visitor IP addresses are not stored as fields in the scan-event record, but infrastructure logs and security/rate-limit processing may still handle IP addresses. A scan record does not establish who scanned a tag or that the pet or item was at that location.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Why we use information","type":"RICH_TEXT","content":{"headline":"Why we use information","copy":"We use information to process and fulfil orders, make agreed personalisation, communicate progress, authenticate accounts and verified guests, activate and manage NFC tags and public profiles, enable intended contact with profile contacts, manage points, answer tickets, detect abuse and meet legal record-keeping requirements. We use limited scan diagnostics to operate and protect the service. You can browse without an account; activation and profile management require one. Withholding information needed for an order or verified request can prevent that transaction. Optional measurement, marketing and visitor location sharing are separate choices.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"What becomes public when a tag is enabled","type":"RICH_TEXT","content":{"headline":"What becomes public when a tag is enabled","copy":"A public profile deliberately displays the profile details and contact information you choose to enter into its available fields. Anyone who knows the public link or can read the enabled tag may see, copy or share the page, photo and phone details; they do not need your account password. Pet medical fields concern the animal, but owner, veterinarian and other contact details can identify people. Avoid publishing unnecessary personal information and obtain the relevant person’s permission. Order, payment, password, ticket and private account information is not published as part of a tag profile. Public tag pages request no indexing by search engines; this reduces discoverability but does not guarantee privacy or prevent copying. Use available visibility and disable controls to stop future public access. An already-sent SMS, saved image or external copy cannot be recalled by changing the profile.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Visitor location sharing, calls and messages","type":"RICH_TEXT","content":{"headline":"Visitor location sharing, calls and messages","copy":"The tag has no GPS and we do not continuously track its wearer or owner. If a visitor chooses Share location, their browser requests location permission. If granted, the current feature uses coordinates on the device to prepare an SMS with a Google Maps link to the public profile contact. The visitor can review and send or cancel it in their SMS app. The coordinates are not uploaded to Tapkin’s server by this feature. The recipient and messaging provider receive them if the visitor sends the message; opening the map link can disclose them to the map provider. Browser/OS, SMS, telephone and map services handle their part under their own policies. Declining location does not prevent viewing a public profile or using available call/SMS options. A phone call or message goes to the displayed contact, not to Tapkin customer support.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Accounts and sign-in providers","type":"RICH_TEXT","content":{"headline":"Accounts and sign-in providers","copy":"Email accounts use password hashes rather than readable passwords, and verification or recovery messages are sent to your email. If you choose Google sign-in, we receive the identity details needed to authenticate you, such as a provider identifier, email and name; Google handles its own sign-in page under its policy. Apple is used only if offered and selected. We do not request access to your mailbox, contacts or unrelated provider content for sign-in. Profile editing does not directly change your login email; contact support about identity or access corrections.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Cookies, local storage and remembering checkout","type":"RICH_TEXT","content":{"headline":"Cookies, local storage and remembering checkout","copy":"Essential cookies and similar storage support sessions, carts, security and your privacy preferences. If offered and you explicitly select Remember my details, contact and delivery details are saved in this browser with an expiry of up to 90 days under the current setting; no card details are included. Expired details are not reused and are removed when checkout next reads them; an inactive browser can retain the stored entry until then or until you clear it. This local storage is different from a server account and is specific to the device and browser. You can use Forget saved details or clear site storage. Do not opt in on a shared device. Saved account addresses are separate and remain until removed or otherwise handled through an account request.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Australian address suggestions","type":"RICH_TEXT","content":{"headline":"Australian address suggestions","copy":"Geoapify address suggestions are optional and operate only when enabled for this store. Queries are filtered to Australia. The part of the address you type is sent through our server to Geoapify so it can suggest addresses; other checkout fields are not included in the suggestion query. Selecting a suggestion can populate address fields, but you must check unit numbers and the final address. Manual entry remains available. Geoapify processes queries under its own service terms and privacy policy.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Google Analytics and Microsoft Clarity","type":"RICH_TEXT","content":{"headline":"Google Analytics and Microsoft Clarity","copy":"If enabled, Google Analytics 4 receives consented shopping and website events to help us understand visits and purchases. Microsoft Clarity may record consented, anonymous browsing of home, shop, FAQ and policy pages with text masked. Our Clarity integration excludes checkout, personalisation, accounts, orders, support tickets, administration and NFC profiles. These tools remain inactive when not configured or enabled and require analytics consent. Masking and exclusions reduce exposure but are not a promise that no technical identifiers are processed by the provider.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Meta advertising and product catalogues","type":"RICH_TEXT","content":{"headline":"Meta advertising and product catalogues","copy":"If enabled and you allow advertising measurement, Meta Pixel and Conversions API receive selected website and confirmed-purchase events, including product identifiers, amounts, currency and event identifiers used to avoid duplication. Browser or advertising identifiers can also be involved. We do not send names, customer contact details, addresses or personalisation text through our shopping measurement integration or enable customer-contact advanced matching. A Meta catalogue feed contains public product information and is separate from customer event tracking. These services do not run merely because this policy describes them.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Your measurement and marketing choices","type":"RICH_TEXT","content":{"headline":"Your measurement and marketing choices","copy":"Use Privacy & cookie settings to allow or decline optional analytics and advertising or change your choice later. Declining does not prevent a purchase or support request. Withdrawal stops future optional collection through our integration; it does not recall information already received by a provider. Browser blocking and provider settings may also limit tracking. Marketing email is a separate opt-in preference, not a condition of ordering. We identify the sender and provide an unsubscribe route in commercial messages, honouring unsubscribe requests within five working days. Essential account, order and ticket messages can still be sent for their service purpose.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Service providers and sharing","type":"RICH_TEXT","content":{"headline":"Service providers and sharing","copy":"We share only information reasonably needed with providers supporting hosting and storage (including Microsoft Azure), payment (Stripe), transactional email (Resend), address suggestions (Geoapify when enabled), shipping (Shippit and the selected carrier) and the optional measurement services described above. Our authorised team accesses information for fulfilment, customer service and administration according to their role. We may disclose information where required by law, to address a safety issue or to establish or defend a legitimate legal claim. We do not publish private orders, tickets or customer designs as marketing material without separate permission.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Overseas processing","type":"RICH_TEXT","content":{"headline":"Overseas processing","copy":"Some providers and their subprocessors process or store information outside Australia. Countries can include the United States and countries in the European Union, depending on the provider, service and configuration; Australian hosting does not make every provider Australian-only. We consider appropriate contracts, security and applicable overseas-disclosure obligations. Ask through a privacy ticket for current provider and location information relevant to your data. A provider’s own account, payment or sign-in service may also collect information directly under its own privacy policy.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Customer points and related brands","type":"RICH_TEXT","content":{"headline":"Customer points and related brands","copy":"Tapkin and Kosykin are registered business names operated by the same proprietor on a shared platform. Account identity and saved delivery addresses can be shared platform features; order access, customer points and store preferences are scoped to the relevant store. NFC tag/profile access depends on authorised ownership and the applicable store. Points use a store-specific ledger of earning, expiry, redemption and refunds. Eligible guest awards can be associated with a protected email-derived identifier and claimed after email verification. A hash reduces direct exposure but does not make linked information anonymous. Points are not automatically transferable between brands.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Retention, security and deletion","type":"RICH_TEXT","content":{"headline":"Retention, security and deletion","copy":"We keep information as reasonably needed for accounts, enabled profiles, fulfilment, support, disputes, security and applicable legal/tax records. Some business records generally need at least five years and certain records require longer; that does not mean every public-profile field must be kept for five years. Tag/profile records may remain while the product service is in use, and historical, security or backup copies can remain for limited operational or legal needs after a change. Ask through a verified Privacy ticket about access, deactivation or deletion and their effect on an active tag. Disabled public access and account deletion are different actions. Order records or audit information we must retain may be restricted instead of erased immediately. Shared account changes can affect access to related-brand services. We use access controls and secure transport, but cannot guarantee absolute security. Browser checkout retention is separate from server records, and we cannot erase copies retained independently by visitors or message recipients.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Access, correction and complaints","type":"RICH_TEXT","content":{"headline":"Access, correction and complaints","copy":"You can edit permitted account details and addresses, manage marketing preferences and download available account information. You can request access, correction, deletion or an explanation through a privacy ticket, including as a verified guest. We reasonably verify your identity before disclosing or changing information. If we cannot fulfil a request in full, we explain why and any available review route. Our initial ticket response target is five business days; a complex privacy request or complaint may take longer. If unresolved, you can contact the OAIC where it has jurisdiction or another relevant regulator. You do not waive legal complaint rights by using our ticket channel.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Children, safety incidents and policy updates","type":"RICH_TEXT","content":{"headline":"Children, safety incidents and policy updates","copy":"Our current shop and account service are intended for adults; current pet products are not a request to publish children’s information. An adult placing an order should provide their own details and avoid unnecessary child or sensitive human information. Where another person’s details are supplied, the account holder must have appropriate authority; tell us about unauthorised disclosure through a Privacy ticket. We assess suspected security incidents, take appropriate containment steps and notify affected people and regulators where legally required. We update this policy and its date when practices change. An update is not consent to new optional marketing, tracking or a different use requiring consent.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}}]}]$content$::jsonb) LOOP
    release_id := overlay(overlay(md5(store_id::text || ':tapkin-policies-20261013:' || (page->>'slug') || ':0') placing '5' from 13 for 1) placing '8' from 17 for 1)::uuid;
    -- Re-running this release must preserve subsequent CMS edits and visibility.
    IF EXISTS (SELECT 1 FROM "LandingPageSection" WHERE id = release_id AND "storeId" = store_id) THEN
      CONTINUE;
    END IF;
    INSERT INTO "ContentPage" (id, "storeId", kind, slug, name, status, "showInFooter", "navigationOrder", "seoTitle", "seoDescription", indexable, "createdAt", "updatedAt")
    VALUES (gen_random_uuid(), store_id, 'LEGAL', page->>'slug', page->>'name', 'PUBLISHED', true,
      500 + page_position, (page->>'name') || ' | Tapkin', page->>'description', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
    ON CONFLICT ("storeId", slug) DO UPDATE SET kind = EXCLUDED.kind, name = EXCLUDED.name,
      status = 'PUBLISHED', "showInFooter" = true, "seoTitle" = EXCLUDED."seoTitle",
      "seoDescription" = EXCLUDED."seoDescription", indexable = true, "updatedAt" = CURRENT_TIMESTAMP;
    SELECT id INTO page_id FROM "ContentPage" WHERE "storeId" = store_id AND slug = page->>'slug';
    UPDATE "LandingPageSection" SET visible = false, "updatedAt" = CURRENT_TIMESTAMP
      WHERE "pageId" = page_id AND "storeId" = store_id;
    SELECT COALESCE(max("sortOrder") + 1, 0) INTO position FROM "LandingPageSection" WHERE "pageId" = page_id;
    FOR section IN SELECT value FROM jsonb_array_elements(page->'sections') WITH ORDINALITY ORDER BY ordinality LOOP
      INSERT INTO "LandingPageSection" (id, "storeId", "pageId", type, name, visible, "sortOrder", content, "createdAt", "updatedAt")
      VALUES (overlay(overlay(md5(store_id::text || ':tapkin-policies-20261013:' || (page->>'slug') || ':' || ((SELECT count(*) FROM "LandingPageSection" WHERE "pageId" = page_id AND visible = true)::text)) placing '5' from 13 for 1) placing '8' from 17 for 1)::uuid,
        store_id, page_id, 'RICH_TEXT', section->>'name', true, position, section->'content', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
      position := position + 1;
    END LOOP;
    page_position := page_position + 1;
  END LOOP;
END $tapkin_policies$;
